from solution import cycpattern_check
import pytest
from hypothesis import given
import hypothesis.strategies as st


def reference(a, b):
    # Obviously correct brute force: all rotations of b checked with `in`.
    # Empty string is a substring of every string.
    if b == "":
        return "" in a
    rotations = set()
    for i in range(len(b)):
        rotations.add(b[i:] + b[:i])
    return any(r in a for r in rotations)


def test_examples_abd():
    assert cycpattern_check("abcd", "abd") is False


def test_examples_ell():
    assert cycpattern_check("hello", "ell") is True


def test_examples_psus():
    assert cycpattern_check("whassup", "psus") is False


def test_examples_baa():
    assert cycpattern_check("abab", "baa") is True


def test_examples_eeff():
    assert cycpattern_check("efef", "eeff") is False


def test_examples_simen():
    assert cycpattern_check("himenss", "simen") is True


def test_empty_b_is_substring():
    # "" is a substring of any string, and its only rotation is itself.
    assert cycpattern_check("abc", "") is True
    assert cycpattern_check("", "") is True
    assert cycpattern_check("hello", "") is True


def test_empty_a_nonempty_b():
    assert cycpattern_check("", "a") is False
    assert cycpattern_check("", "abc") is False


def test_single_char_present():
    assert cycpattern_check("abc", "b") is True
    assert cycpattern_check("abc", "c") is True
    assert cycpattern_check("abc", "a") is True


def test_single_char_absent():
    assert cycpattern_check("abc", "z") is False


def test_exact_rotation_match():
    # "baa" rotations: baa, aab, aba; "abab" contains "aba"
    assert cycpattern_check("abab", "aab") is True
    assert cycpattern_check("abab", "aba") is True


def test_direct_substring_implies_true():
    # 0-rotation is b itself, so b in a => True
    assert cycpattern_check("hello world", "o w") is True
    assert cycpattern_check("abcd", "abcd") is True
    assert cycpattern_check("abcd", "bc") is True


@given(
    a=st.text(alphabet="abc", min_size=0, max_size=8),
    b=st.text(alphabet="abc", min_size=0, max_size=5),
)
def test_reference_model(a, b):
    assert cycpattern_check(a, b) == reference(a, b)


@given(
    a=st.text(alphabet="abcd", min_size=0, max_size=10),
    b=st.text(alphabet="abcd", min_size=1, max_size=5),
    k=st.integers(min_value=0, max_value=5),
)
def test_rotation_invariance(a, b, k):
    # Rotating b does not change the set of rotations, so result is invariant.
    r = b[k % len(b):] + b[: k % len(b)]
    assert cycpattern_check(a, b) == cycpattern_check(a, r)


@given(
    a=st.text(alphabet="abc", min_size=0, max_size=8),
    b=st.text(alphabet="abc", min_size=1, max_size=5),
)
def test_true_implies_len_fits(a, b):
    if cycpattern_check(a, b) is True:
        assert len(b) <= len(a)


@given(
    a=st.text(alphabet="abc", min_size=0, max_size=8),
    b=st.text(alphabet="abc", min_size=1, max_size=8),
)
def test_longer_b_is_false(a, b):
    # A rotation has same length as b, so it cannot fit in shorter a.
    if len(b) > len(a):
        assert cycpattern_check(a, b) is False


@given(
    a=st.text(alphabet="ab", min_size=0, max_size=8),
    b=st.text(alphabet="ab", min_size=0, max_size=4),
    pad=st.text(alphabet="ab", min_size=0, max_size=4),
)
def test_extending_a_preserves_true(a, b, pad):
    # Adding characters to a cannot remove an existing substring match.
    if cycpattern_check(a, b) is True:
        assert cycpattern_check(a + pad, b) is True
        assert cycpattern_check(pad + a, b) is True


@given(n=st.integers(min_value=1, max_value=5))
def test_repeated_char_rotation(n):
    # All rotations of "x"*n are identical.
    assert cycpattern_check("a" * n + "b" + "a" * n, "a" * n) is True
    assert cycpattern_check("bbbb", "a" * n) is False
